/// Returns whether [path]'s row is currently within the visible viewport.
///
/// Prefer an intersection test when the row has been built; when the row
/// is offscreen Flutter may not build it at all, so we conservatively
/// return false.
bool isTrackVisible(String path) {
  if (!isMounted()) return false;
  if (!scroll.hasClients) return false;

  // Only tracks that belong to the current folder are addressable.
  final tracks = ctrl.tracks;
  final index = tracks.indexWhere((t) => t.path == path);
  if (index < 0) return false;

  final rowContext = rowKeys[path]?.currentContext;
  if (rowContext == null) return false;

  final rowBox = rowContext.findRenderObject();
  final viewportBox = scroll.position.context.findRenderObject();
  if (rowBox is! RenderBox || viewportBox is! RenderBox) return false;
  if (!rowBox.hasSize || !viewportBox.hasSize) return false;

  final rowRect = rowBox.localToGlobal(Offset.zero) & rowBox.size;
  final viewportRect =
      viewportBox.localToGlobal(Offset.zero) & viewportBox.size;

  return rowRect.overlaps(viewportRect);
}

// Register the scroll-to-track + visibility probes onto the passed handle;
